wrong_example:
C <- 10
output("C")
{ siswa kira ini mencetak isi C, padahal mencetak huruf 'C' }

age <- 20
output(Age)
{ siswa kira age dan Age variabel yang sama }

correct_example:
age <- 20
output(age)
{ nama variabel case-sensitive: age != Age }

A <- 5
nama <- "Hero"
{ tipe berbeda tidak dicampur langsung dalam satu operasi aritmatika }
